BEGIN;
SELECT pg_catalog.set_config('request.jwt.claim', '{"aal":"aal2"}', true);
SELECT plan(22);
INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at) VALUES
('e1a00000-0000-4000-8000-000000000001','authenticated','authenticated','cart-admin@example.test','{}',now(),now()),
('e1a00000-0000-4000-8000-000000000002','authenticated','authenticated','cart-owner@example.test','{}',now(),now()),
('e1a00000-0000-4000-8000-000000000003','authenticated','authenticated','cart-other@example.test','{}',now(),now());
INSERT INTO public.user_roles(user_id,role,granted_by) VALUES('e1a00000-0000-4000-8000-000000000001','admin','e1a00000-0000-4000-8000-000000000001');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1a00000-0000-4000-8000-000000000001',true);
SELECT set_config('c.a',public.admin_save_course_content('cart-check-a','en','Cart course A','Fixture','',30000,'','beginner',true)::text,true);
SELECT set_config('c.b',public.admin_save_course_content('cart-check-b','en','Cart course B','Fixture','',20000,'','beginner',true)::text,true);
SELECT set_config('c.free',public.admin_save_course_content('cart-check-free','en','Free course','Fixture','',0,'','beginner',true)::text,true);
SELECT set_config('request.jwt.claim.sub','e1a00000-0000-4000-8000-000000000002',true);
SELECT set_config('c.order',public.learner_create_cart_order(ARRAY[current_setting('c.b')::uuid,current_setting('c.a')::uuid,current_setting('c.b')::uuid],'en')::text,true);
SELECT is((SELECT subtotal_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),50000::bigint,'cart subtotal is the server price sum');
SELECT is((SELECT total_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),50000::bigint,'cart total starts at the subtotal');
SELECT is((SELECT count(*)::int FROM public.order_items WHERE order_id=current_setting('c.order')::uuid),2,'duplicate ids collapse to one item each');
SELECT is((SELECT amount_minor FROM public.order_items WHERE order_id=current_setting('c.order')::uuid AND course_id=current_setting('c.a')::uuid),30000::bigint,'each item snapshots its own price');
SELECT is((SELECT array_agg(course_id ORDER BY position) FROM public.order_items WHERE order_id=current_setting('c.order')::uuid),ARRAY[current_setting('c.b')::uuid,current_setting('c.a')::uuid],'items keep the cart order');
SELECT is(public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid,current_setting('c.b')::uuid],'en'),current_setting('c.order')::uuid,'same cart in another order reuses the pending order');
SELECT isnt(public.learner_create_order(current_setting('c.a')::uuid,'en'),current_setting('c.order')::uuid,'buy now never reuses a multi-course cart order');
SELECT is(public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid],'en'),current_setting('c.order')::uuid,'an edited cart rewrites the open unpaid cart order');
SELECT is((SELECT subtotal_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),30000::bigint,'rewritten order is repriced');
SELECT is((SELECT count(*)::int FROM public.order_items WHERE order_id=current_setting('c.order')::uuid),1,'rewritten order holds only the new items');
SELECT is(public.learner_create_cart_order(ARRAY[current_setting('c.b')::uuid,current_setting('c.a')::uuid],'en'),current_setting('c.order')::uuid,'editing back reuses the same order again');
SELECT is((SELECT count(*)::int FROM public.orders),2,'cart edits create no extra orders');
SELECT throws_ok($$SELECT public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid,current_setting('c.free')::uuid],'en')$$,'P0002',NULL,'free course cannot be bought in a cart');
SELECT throws_ok($$SELECT public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid],'ar')$$,'P0002',NULL,'missing exact-locale publication denied');
SELECT throws_ok($$SELECT public.learner_create_cart_order(ARRAY[]::uuid[],'en')$$,'22023',NULL,'empty cart rejected');
SELECT throws_ok($$SELECT public.learner_create_cart_order((SELECT array_agg(gen_random_uuid()) FROM generate_series(1,21)),'en')$$,'22023',NULL,'oversized cart rejected');
SELECT set_config('request.jwt.claim.sub','e1a00000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::int FROM public.order_items WHERE order_id=current_setting('c.order')::uuid),0,'another account cannot read cart items');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.commerce_bind_session(current_setting('c.order')::uuid,'0123456789abcdef01234568','https://payments.kashier.io/session/0123456789abcdef01234568?mode=test',50000);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1a00000-0000-4000-8000-000000000002',true);
SELECT isnt(public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid],'en'),current_setting('c.order')::uuid,'an order with a payment session is never rewritten');
SELECT is((SELECT subtotal_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),50000::bigint,'bound order keeps its amount');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234568','provider-cart',50000,'EGP','paid','cart-capture');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.enrollments WHERE user_id='e1a00000-0000-4000-8000-000000000002' AND grant_source='paid'),2,'paid cart grants every course once');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1a00000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.learner_create_cart_order(ARRAY[current_setting('c.a')::uuid],'en')$$,'23514',NULL,'owned course cannot be bought again');
RESET ROLE;
SELECT ok(NOT has_function_privilege('anon','public.learner_create_cart_order(uuid[],text)','EXECUTE'),'anonymous cart checkout denied');
SELECT * FROM finish();ROLLBACK;
